"""Add explicit primary-result interpretations, retaining earlier recorded text."""
from pathlib import Path
import json,sys,subprocess
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from scripts import z13_candidates_night as n

def main():
    out=n.OUT; marker=out/'finish_interpretation_recorded.json'
    assert not marker.exists() and n.read(out/'recovery2_finish_recorded.json')['finish']
    assert n.read(out/'recovery2_controller_result.json')['exit_code']==0
    report=n.read(out/'report.json'); assert len(list(out.glob('*/*/completed.json')))==15
    now=n.now(); commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
    catpath=ROOT/'experiments/project_history.json'; cat=n.read(catpath)
    interpretations={
        'foreground':'Считывание с контрастом окружения не улучшило нахождение цели относительно такого же продолжения без этого узла: средняя по видео доля полезных центров 19,390% → 19,163%, разность −0,227 п.п., 95% ДИ [−1,550; +1,111] п.п. (runs/z13_candidates_20261016/report.json → stats.D_base, stats.D_foreground, comparisons.D_foreground-D_base). Сравнение D с B положительно, но оно не доказывает пользу добавленного узла; преимущество над C здесь не подтверждено. Причина ошибок исходного представления цели этим опытом не локализована.',
        'size':'Новый размер ухудшил средний по видео IoU при тех же предсказанных центрах: 0,342418 → 0,319914, разность −0,022504, 95% ДИ [−0,030130; −0,017160] (runs/z13_candidates_20261016/report.json → stats.D_size и comparisons.D_size_delta). Исходный размер — последняя наблюдавшаяся рамка, а не текущий прогноз Калмана. Положительное сравнение D с B/C не отменяет ухудшение размеров внутри D; B/C/D имеют разные центры. Это не результат точности рамок штатного трекера.',
        'adaptive':'Адаптивное накопление не улучшило фиксированное: средняя по видео доля полезных центров 18,784% → 16,739%, разность −2,045 п.п., 95% ДИ [−6,940; +1,157] п.п. (runs/z13_candidates_20261016/report.json → stats.D_fixed, stats.D_adaptive, comparisons.D_adaptive-D_fixed). Доля ошибок среди известных исходов верхнего 1% снизилась с 27/37 до 25/37, но основной критерий локализации не выполнен. Преимущество над B есть в этом пилоте; над C не подтверждено.'}
    for mode,interpretation in interpretations.items():
        card=next(c for c in cat['experiments'] if c['id']=='z13_candidate_'+mode+'_v1')
        for field,value in [('interpretation',interpretation),('decision','Эта реализация не прошла принятый функциональный критерий. Сохранить модели и полный результат; автоматический HOTA-прогон и подбор новых настроек не запускать. Причину провала более широкого направления считать не установленной.'),('cannot_claim','Нельзя объявлять улучшение HOTA, независимое подтверждение, бесполезность узла вообще или причинную роль анатомии мухи. Проверены один сид и 500 шагов на многократно использованных train26; ядра фиксированы, контроль B не равен FlyVis по числу параметров.')]:
            if card.get(field)!=value:
                card.setdefault('revisions',[]).append(dict(date=now.date().isoformat(),commit=commit,field=field,old=card.get(field,''),reason='Уточнение полного отрицательного итога по первичному report.json без изменения чисел или критериев'))
                card[field]=value
    catpath.write_text(json.dumps(cat,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
    entry=f'''**{now:%d.%m.%Y, %H:%M} MSK** — полный отрицательный итог трёх отдельных узлов FlyVis

*Постановка.* Завершены все 15 заранее записанных заданий B/C/D, по 500 шагов, train104/26; ядра фиксированы. Текущий GPU-процесс закончил работу в 04:24:40 с кодом 0, это подтверждено recovery2_controller_result.json и отсутствием процессов текущего контроллера/рабочего запуска. Все completed.json, контрольные суммы предсказаний и 285 исходных файлов проверены; CPU-анализ выполнен один раз. Источник чисел: runs/z13_candidates_20261016/report.json.

*Получено (`z13_candidate_foreground_v1`).* D с окружением против D без нового узла: доля полезных центров в среднем по видео 19,390% → 19,163%; −0,227 п.п. [−1,550; +1,111]. Относительная разность −1,17%. D против B при том же узле: +6,484 п.п. [+2,409; +11,406]. Три условия: false/true/true, общий критерий не выполнен.

*Получено (`z13_candidate_size_v1`).* При одинаковых центрах D средний по видео IoU со старым/новым размером: 0,342418 → 0,319914; −0,022504 [−0,030130; −0,017160], относительно старого размера −6,57%. D size против B size: +0,142664 [+0,111126; +0,184857], но центры B/D различаются. Исходный размер — последняя наблюдавшаяся рамка. Три условия: false/true/true, общий критерий не выполнен. Техническая проверка неизменности исходного считывания пройдена на одной и той же активности ядра; прежний сбой двух отдельных численных проходов сохранён в журнале.

*Получено (`z13_candidate_adaptive_v1`).* D адаптивный против D фиксированный: доля полезных центров 18,784% → 16,739%; −2,045 п.п. [−6,940; +1,157], относительная разность −10,88%. D адаптивный против B адаптивного: +4,478 п.п. [+0,789; +8,149]. Три условия: false/true/true, общий критерий не выполнен.

*Вывод.* Все три конкретные реализации не прошли критерии. Положительные сравнения D/B сами по себе не подтверждают пользу новых узлов. Корневая причина ошибок представления цели, входа либо обучения не установлена. Это функциональный пилот с одним сидом на повторно использованных train26, а не независимая проверка или измерение трекинга.

*Решение.* Сохранить все модели и результаты. В этом запуске новых научных опытов и HOTA не ставить, критерии не ослаблять. HOTA не измерялась, процент к стенду и доля оракульного запаса не определены; приведённые относительные проценты относятся только к соответствующим функциональным контролям. Существующая .git/index.lock не удаляется; коммит/push заблокирован.

'''
    plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md'; text=plan.read_text(encoding='utf-8'); anchor='## Журнал изменений\n\n'; assert text.count(anchor)==1
    plan.write_text(text.replace(anchor,anchor+entry,1),encoding='utf-8')
    research=ROOT/'research_flyvis_china_2026-10-15/ПЛАН_ПРОБ.md'
    old=research.read_text(encoding='utf-8')
    research.write_text(old+'\n\n## 7. Полученный итог 16.10.2026\n\nВсе 15 заданий завершены; отчёт — `runs/z13_candidates_20261016/report.json`. Ни одна из трёх реализаций не прошла заранее заданный основной критерий. Подавление окружения: −0,227 п.п. доли полезных центров [−1,550; +1,111]; адаптивное накопление: −2,045 п.п. против фиксированного [−6,940; +1,157]. Новый размер при тех же центрах ухудшил IoU на 0,022504 [0,017160; 0,030130]. Преимущество D над контролем B в этих пилотах не доказывает пользу добавленного узла. Исходные постановка, критерии и прежние записи выше сохранены. HOTA и независимая проверка не проводились; автоматического следующего обучения или HOTA этот результат не разрешает.\n',encoding='utf-8')
    n.write(marker,dict(at=now.isoformat(),report_sha256=n.sha(out/'report.json')))

if __name__=='__main__': main()
